#define MAX_TEXT 5000
#define CHAT_FONT_SIZE 18
#define CHAT_LINE_HEIGHT 22
#define STATUS_FONT_SIZE 20

// Text shown on start screen. Keep it short so it fits small windows.
#define GAME_TITLE "Battleships"
#define DEDICATION_TEXT "In memory of Mārtiņš Grinfelds, friend and co-author."

static Font title_font;
static int title_font_loaded = 0;

char *get_user_input(uint16_t min, uint16_t max)
{
    // FIXME: min and max doesn't work. Replace with graphical library input.
    if (min > max) {
        fprintf(stderr, "Invalid input: min should be less than or equal to max.\n");
        return NULL;
    }
    // Call free(address) for this one or enjoy memory leak 😍
    char *buffer = malloc(max + 1);  // +1 for the null terminator
    if (buffer == NULL) {
        perror("malloc failed");
        return NULL;
    }
    while (1) {
        printf("Please enter a string between %d and %d characters: ", min, max);
        if (fgets(buffer, max + 1, stdin) == NULL) {
            perror("fgets failed");
            free(buffer);
            return NULL;
        }

        // Remove the newline character, if present (not ChatGPT -> and last char \0)
        buffer[strcspn(buffer, "\n")] = '\0';

        // Check the length of the input
        size_t length = strlen(buffer);
        if (length >= min && length <= max) {
            return buffer;  // Valid input, return the buffer
        }

        printf("Input must be between %d and %d characters. You entered %zu characters.\n", min, max, length);
    }
}

void load_ui_fonts()
{
    title_font = LoadFont_DedicationFont();
    SetTextureFilter(title_font.texture, TEXTURE_FILTER_BILINEAR);
    title_font_loaded = 1;
}

void unload_ui_fonts()
{
    if (title_font_loaded)
    {
        // Glyph data is static (generated code), only texture is unloaded.
        UnloadTexture(title_font.texture);
        title_font_loaded = 0;
    }
}

static Font get_title_font()
{
    return title_font_loaded ? title_font : GetFontDefault();
}

/// @brief Draws text with title font centered horizontally.
static void draw_centered_title_text(const char *text, int y, float size, Color color)
{
    Font font = get_title_font();
    Vector2 measure = MeasureTextEx(font, text, size, 1);
    DrawTextEx(font, text, (Vector2){(GetScreenWidth() - measure.x) / 2, (float)y}, size, 1, color);
}

static void draw_centered_text(const char *text, int y, int size, Color color)
{
    DrawText(text, (GetScreenWidth() - MeasureText(text, size)) / 2, y, size, color);
}

void draw_dedication(int y)
{
    draw_centered_title_text(GAME_TITLE, y, 72, SHIP_COLOR);
    draw_centered_title_text(DEDICATION_TEXT, y + 100, 26, PLACED_SHIP_COLOR);
}

void draw_center_message(const char *title, const char *message)
{
    int y = GetScreenHeight() / 2 - 60;
    draw_centered_title_text(title, y, 48, SHIP_COLOR);
    if (message)
    {
        draw_wrapped_text(message, GetScreenWidth() / 6, y + 70, GetScreenWidth() * 2 / 3, 22, ColorToInt(PLACED_SHIP_COLOR));
    }
}

void draw_map_area(uint8_t width, uint8_t height, uint8_t *map)
{
    struct MapLayout layout = get_map_layout(width, height);
    int square = layout.cell;
    int x = 0, y = 0;
    Color color = BLANK;
    uint8_t object_type;

    while (y < height)
    {
        while (x < width)
        {
            if (map)
            {
                object_type = map[get_map_index(width, x, y)];
            }
            else
            {
                object_type = 0;
            }
            switch (object_type)
            {
            case FOW_SEA:
                color = FOW_SEA_COLOR;
                break;

            case VISIBLE_SEA:
                color = SEA_COLOR;
                break;

            case ZONE_SEA:
                color = ZONE_COLOR;
                break;

            case ALLIED_SHIP:
            case ALLIED_SHIP_TAIL:
                color = SHIP_COLOR;
                break;

            case TEAMMATE_SHIP:
            case TEAMMATE_SHIP_TAIL:
                color = TEAMMATE_COLOR;
                break;

            case ENEMY_SHIP:
            case ENEMY_SHIP_TAIL:
                color = ENEMY_COLOR;
                break;

            case PLACED_SHIP:
            case PLACED_SHIP_TAIL:
                color = PLACED_SHIP_COLOR;
                break;

            case INVALID_PLACED_SHIP:
                color = INVALID_COLOR;
                break;

            case SUNK_SHIP:
                color = SUNK_COLOR;
                break;

            default:
                color = GREEN;
            }
            DrawRectangle(layout.x + x * square, layout.y + y * square, square, square, color);
            if (square >= 6)
            {
                DrawRectangleLines(layout.x + x * square, layout.y + y * square, square, square, FOW_SEA_COLOR);
            }
            x++;
        }
        x = 0;
        y++;
    }
    DrawRectangleLines(layout.x, layout.y, width * square, height * square, SEA_COLOR);
}

char* get_username_input(uint8_t min, uint8_t max, char *message, const char *server)
{
    // Call free(address) for this one or enjoy memory leak 😍
    char* username = calloc((max + 1), sizeof(char));
    int letter_count = 0, key = 0, font_size = 40, min_text_warning = 0;
    SetTargetFPS(50);

    while (!WindowShouldClose())    // Detect window close button
    {
        int center_y = GetScreenHeight() / 2;
        Rectangle text_box = { 0, (float)center_y, 500, 56 };
        BeginDrawing();

            ClearBackground(FOW_SEA_COLOR);
            draw_dedication(center_y - 300);

            draw_centered_text(message, center_y - 40, 22, SHIP_COLOR);
            int input_size = MeasureText(username, font_size);
            text_box.width = input_size + 20 > 300 ? input_size + 20 : 300;
            text_box.x = (GetScreenWidth() - text_box.width) / 2;

            DrawRectangleRec(text_box, LIGHTGRAY);
            DrawRectangleLines((int)text_box.x, (int)text_box.y, (int)text_box.width, (int)text_box.height, ENEMY_COLOR);

            DrawText(username, (int)text_box.x + 10, (int)text_box.y + 8, font_size, FOW_SEA_COLOR);

            draw_centered_text(TextFormat("Your input length: %i/%i", letter_count, max), center_y + 70, 20, PLACED_SHIP_COLOR);

            if(min_text_warning)
            {
                draw_centered_text(TextFormat("Input must be at least: %i characters long!", min), center_y + 95, 20, ENEMY_COLOR);
            }
            if (server)
            {
                draw_centered_text(TextFormat("Server: %s", server), GetScreenHeight() - 40, 18, GRAY);
            }

        EndDrawing();

        // Get char pressed (unicode character) on the queue
        key = GetCharPressed();

        // NOTE: Only allow keys in range [32..125]
        if ((key >= 32) && (key <= 125) && (letter_count < max))
        {
            min_text_warning = 0;
            username[letter_count] = (char)key;
            username[letter_count+1] = '\0'; // Add null terminator at the end of the string.
            letter_count++;
        }

        if (IsKeyPressed(KEY_BACKSPACE) || IsKeyPressedRepeat(KEY_BACKSPACE))
        {
            letter_count--;
            if (letter_count < 0) letter_count = 0;
            username[letter_count] = '\0';
        }
        if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_KP_ENTER))
        {
            // Spaces at start and end are not allowed by server.
            while (letter_count > 0 && username[letter_count - 1] == ' ')
            {
                username[--letter_count] = '\0';
            }
            if (letter_count < min)
            {
                min_text_warning = 1;
            }
            else
            {
                return username;
            }
        }
        key = 0;
    }
    free(username);
    return NULL;
}

/// @brief Finds how much of text fits into one line.
/// @return Count of characters for line (without trailing space or new line).
static int fit_line(const char *text, int width, int font_size, int *skip)
{
    char line[512];
    int length = 0, last_space = -1;
    *skip = 0;
    while (text[length] && text[length] != '\n' && length < (int)sizeof(line) - 1)
    {
        line[length] = text[length];
        line[length + 1] = '\0';
        if (MeasureText(line, font_size) > width && length > 0)
        {
            if (last_space > 0)
            {
                *skip = 1; // Skip space where line was broken.
                return last_space;
            }
            return length;
        }
        if (text[length] == ' ')
        {
            last_space = length;
        }
        length++;
    }
    if (text[length] == '\n')
    {
        *skip = 1;
    }
    return length;
}

/// @brief Counts lines that text takes with word wrap.
static int count_wrapped_lines(const char *text, int width, int font_size)
{
    int lines = 0;
    while (*text)
    {
        int skip;
        int length = fit_line(text, width, font_size, &skip);
        text += length + skip;
        lines++;
    }
    return lines ? lines : 1;
}

int draw_wrapped_text(const char *text, int x, int y, int width, int font_size, uint32_t color_rgba)
{
    Color color = GetColor(color_rgba);
    int line_height = font_size + 4, start_y = y;
    char line[512];
    while (text && *text)
    {
        int skip;
        int length = fit_line(text, width, font_size, &skip);
        memcpy(line, text, length);
        line[length] = '\0';
        DrawText(line, x, y, font_size, color);
        y += line_height;
        text += length + skip;
    }
    return y - start_y;
}

void show_chat_messages(struct Message* messages, const char *input_line, int input_active)
{
    int screen_x = GetScreenWidth(), screen_y = GetScreenHeight();
    Rectangle container = { 0, (float)(screen_y - CHAT_AREA_HEIGHT), (float)(screen_x - STATUS_AREA_WIDTH), CHAT_AREA_HEIGHT };
    Color borderColor = input_active ? SELECTED_COLOR : ENEMY_COLOR;
    DrawRectangleLinesEx(container, 3, borderColor);    // Draw container border

    int text_width = (int)container.width - 16;
    int input_y = (int)(container.y + container.height) - CHAT_LINE_HEIGHT - 6;
    DrawLine((int)container.x + 3, input_y - 4, (int)(container.x + container.width) - 3, input_y - 4, SUNK_COLOR);
    if (input_line)
    {
        DrawText(input_line, (int)container.x + 8, input_y, CHAT_FONT_SIZE, input_active ? SELECTED_COLOR : GRAY);
    }

    // Collect latest messages that fit. Newest message is at the bottom.
    int total_msg_count = 0;
    struct Message *curr_msg = messages;
    while (curr_msg != NULL) {
        total_msg_count++;
        curr_msg = curr_msg->next_message;
    }
    static char *texts[256];
    static int is_system[256];
    int start_index = total_msg_count > 256 ? total_msg_count - 256 : 0, index = 0, count = 0;
    curr_msg = messages;
    while (curr_msg != NULL)
    {
        if (index++ >= start_index && curr_msg->sender_name && curr_msg->receiver_name && curr_msg->message)
        {
            // In form: (SENDER)->(RECEIVER):MESSAGE
            char *text = malloc(strlen(curr_msg->sender_name) + strlen(curr_msg->receiver_name) + strlen(curr_msg->message) + 8);
            sprintf(text, "(%s)->(%s):%s", curr_msg->sender_name, curr_msg->receiver_name, curr_msg->message);
            is_system[count] = strcmp(curr_msg->sender_name, "Server") == 0;
            texts[count++] = text;
        }
        curr_msg = curr_msg->next_message;
    }
    int bottom = input_y - 8, top = (int)container.y + 6;
    int i = count - 1;
    while (i >= 0)
    {
        int height = count_wrapped_lines(texts[i], text_width, CHAT_FONT_SIZE) * CHAT_LINE_HEIGHT;
        if (bottom - height < top)
        {
            break;
        }
        bottom -= height;
        draw_wrapped_text(texts[i], (int)container.x + 8, bottom, text_width, CHAT_FONT_SIZE, ColorToInt(is_system[i] ? GRAY : WHITE));
        i--;
    }
    i = 0;
    while (i < count)
    {
        free(texts[i++]);
    }
}

static int draw_separator(int x, int y)
{
    DrawLine(x, y + 8, GetScreenWidth() - 15, y + 8, GRAY);
    return y + 18;
}

void draw_status_area(char *player_name, uint8_t player_id, uint8_t team_id, struct StatePacket *state, char *game_message,
                      char *action_message, char *timer_message, char *ships_text)
{
    int starting_x = GetScreenWidth() - STATUS_AREA_WIDTH + 15, font_size = STATUS_FONT_SIZE;
    int width = STATUS_AREA_WIDTH - 30;
    int y_position = 15;
    if (player_name)
    {
        DrawText("Your Name:", starting_x, y_position, font_size, GRAY);
        y_position += 22;
        DrawText(player_name, starting_x, y_position, font_size, WHITE);
        y_position += 24;
    }
    DrawText(TextFormat("Your ID: %d", player_id), starting_x, y_position, font_size, WHITE);
    y_position += 22;
    DrawText(team_id ? TextFormat("Your Team: %d", team_id) : "Your Team: Observer", starting_x, y_position, font_size, WHITE);
    y_position += 22;
    y_position = draw_separator(starting_x, y_position);
    if (game_message && game_message[0])
    {
        y_position += draw_wrapped_text(game_message, starting_x, y_position, width, font_size, ColorToInt(ENEMY_COLOR));
    }
    if (timer_message && timer_message[0])
    {
        y_position += draw_wrapped_text(timer_message, starting_x, y_position, width, font_size, ColorToInt(WHITE));
    }
    y_position = draw_separator(starting_x, y_position);
    if (action_message && action_message[0])
    {
        y_position += draw_wrapped_text(action_message, starting_x, y_position, width, 18, ColorToInt(YELLOW));
        y_position = draw_separator(starting_x, y_position);
    }
    if (ships_text && ships_text[0])
    {
        DrawText("Your Ships:", starting_x, y_position, font_size, GRAY);
        y_position += 24;
        y_position += draw_wrapped_text(ships_text, starting_x, y_position, width, 18, ColorToInt(SHIP_COLOR));
        y_position = draw_separator(starting_x, y_position);
    }
    DrawText("Players (Their Team):", starting_x, y_position, font_size, GRAY);
    y_position += 24;
    char *player_info = get_player_info(state, player_id);
    draw_wrapped_text(player_info, starting_x, y_position, width, 18, ColorToInt(WHITE));
    free(player_info);
}

char *get_player_info(struct StatePacket *state, uint8_t player_id)
{
    char *final_players;
    if (!state || state->player_count == 0 || !state->players)
    {
        final_players = calloc(sizeof("NO PLAYERS") + 1, sizeof(char));
        strcpy(final_players, "NO PLAYERS");
        return final_players;
    }
    size_t size = (size_t)state->player_count * (MAX_USERNAME + 32) + 1;
    final_players = calloc(size, sizeof(char));
    size_t i = 0, used = 0;
    while (i < state->player_count && used < size)
    {
        struct Player *player = &state->players[i++];
        const char *team = player->team_id ? TextFormat("%d", player->team_id) : "Observer";
        used += snprintf(final_players + used, size - used, "%s%s (%s)%s\n", player->id == player_id ? "> " : "",
                         player->username, team, player->status == PLAYER_STATUS_DISCONNECTED ? " Offline" : "");
    }
    return final_players;
}

void draw_end_game_overlay(uint8_t width, uint8_t height, const char *title, const char *subtitle)
{
    struct MapLayout layout = get_map_layout(width, height);
    int map_width = layout.cell * width, map_height = layout.cell * height;
    Rectangle box = {(float)(layout.x + map_width / 10), (float)(layout.y + map_height / 3), (float)(map_width * 8 / 10), 150};
    DrawRectangleRec(box, (Color){14, 14, 14, 245});
    DrawRectangleLinesEx(box, 3, SELECTED_COLOR);
    Font font = get_title_font();
    Vector2 measure = MeasureTextEx(font, title, 48, 1);
    DrawTextEx(font, title, (Vector2){box.x + (box.width - measure.x) / 2, box.y + 25}, 48, 1, SELECTED_COLOR);
    if (subtitle)
    {
        DrawText(subtitle, (int)(box.x + (box.width - MeasureText(subtitle, 20)) / 2), (int)box.y + 95, 20, WHITE);
    }
}
